describe('teams, discussion and peer signaling',()=>{

 it('delivers a live batch in sequence before its watermark',async()=>{const a=await user(),team=await paidTeam(a),p=await seeded(a.token,team);const response=await app.fetch(`https://scriv.test/v1/projects/${p}/socket`,{headers:{authorization:`Bearer ${a.token}`,upgrade:'websocket'}}),socket=response.webSocket!;sockets.push(socket);const hello=waitMessage(socket,v=>v.type==='hello');socket.accept();await hello;const received:number[]=[];socket.addEventListener('message',(event:MessageEvent)=>{const value=JSON.parse(String(event.data));if(value.type==='events')received.push(...value.events.map((e:any)=>e.seq));});const commands=await Promise.all(['A','B','C'].map(label=>call(`/v1/projects/${p}/commands`,a.token,'POST',command([put(scene(label))]))));expect(commands.every(r=>r.status===200)).toBe(true);const watermark=waitMessage(socket,v=>v.type==='watermark');socket.send(JSON.stringify({type:'ping',after:1}));expect((await watermark).headSeq).toBe(4);expect(received).toEqual([2,3,4]);});
});
