it('retains reference and word validation for text edits with unchanged geometry',async()=>{
 const a=await user(),p=await seeded(a.token),lease=(await claim(p,a.token)).data;
 const next=entry();next.data.text='Goodbye world.';next.data.words[0]!.text='Goodbye';
 const invalidReference={...next,data:{...next.data,characterId:'missing-character'}};
 const rejected=await call(`/v1/projects/${p}/commands`,a.token,'POST',command([put(invalidReference,1,lease)]));
 expect(rejected.status).toBe(400);expect(rejected.data.error.code).toBe('invalid_reference');
 const invalidWords=structuredClone(next);invalidWords.data.words[0]!.text='Different';
 expect((await call(`/v1/projects/${p}/commands`,a.token,'POST',command([put(invalidWords,1,lease)]))).data.error.code).toBe('word_order');

it('rejects out-of-bounds and overlapping cues after geometry edits and rolls back',async()=>{
 const a=await user(),p=await seeded(a.token),entryLease=(await claim(p,a.token)).data;
 const cue=(id:string,startMs:number,endMs:number)=>({id,kind:'cue',data:{id,sceneId:'scene',label:id,prompt:'',startMs,endMs}});
 expect((await call(`/v1/projects/${p}/commands`,a.token,'POST',command([put(cue('first',0,1000)),put(cue('second',1000,2000))]))).status).toBe(200);
 const firstLease=(await call(`/v1/projects/${p}/leases`,a.token,'POST',{itemId:'first',sessionId:'editor-A'})).data;
 const shortened=entry();shortened.data.ownedDurationMs=1500;shortened.data.words[1]!.endMs=1500;
 const outOfBounds=await call(`/v1/projects/${p}/commands`,a.token,'POST',command([put(shortened,1,entryLease)],{expectedTimingVersion:2}));
 expect(outOfBounds.status).toBe(409);expect(outOfBounds.data.error.code).toBe('cue_timing');

 it('pages discussion messages without gaps when timestamps coincide',async()=>{const a=await user(),p=await seeded(a.token),t=(await call(`/v1/projects/${p}/threads`,a.token,'POST',{itemId:'entry'})).data.thread;await runInDurableObject(env.PROJECTS.get(env.PROJECTS.idFromName(p)),(_instance,state)=>{state.storage.transactionSync(()=>{for(let i=0;i<501;i++)state.storage.sql.exec('INSERT INTO messages(id,thread_id,user_id,name,body,attachments,at)VALUES(?,?,?,?,?,?,?)',`message-${String(i).padStart(4,'0')}`,t.id,a.uid,'Alex','Text','[]',1000);});});const page=(await call(`/v1/projects/${p}/threads/${t.id}/messages`,a.token)).data;expect(page.messages).toHaveLength(500);const next=(await call(`/v1/projects/${p}/threads/${t.id}/messages?after=${page.nextCursor.at}&afterId=${page.nextCursor.id}`,a.token)).data;expect(next.messages).toHaveLength(1);expect(next.messages[0].id).toBe('message-0500');});

});
describe('media and billing',()=>{

